package dev.dcrk

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertSame

class ModuleLabelsTest {
    @Test
    fun originalLabelsAndSettingOrderArePreserved() {
        val stringify: dynamic = js("JSON.stringify")
        assertEquals("""{"name":"콘텐츠 차단","description":"보고 싶지 않은 유저, 글, 댓글을 숨기거나 흐리게 합니다.","settings":{"replyRemove":{"name":"대댓글도 가리기","desc":"차단된 댓글의 대댓글도 함께 가립니다."},"blur":{"group":{"name":"흐리게 처리","desc":"차단된 내용을 숨기지 않고 흐리게 처리합니다."},"name":"사용","desc":"차단된 내용을 흐리게 처리합니다."},"blurReveal":{"group":{"name":"흐리게 처리","desc":"차단된 내용을 숨기지 않고 흐리게 처리합니다."},"name":"마우스를 올리면 보기","desc":"흐리게 처리된 내용에 마우스를 올린 동안 원래대로 보여 줍니다."},"blurStrength":{"group":{"name":"흐리게 처리","desc":"차단된 내용을 숨기지 않고 흐리게 처리합니다."},"name":"강도","desc":"차단된 내용을 흐리게 하는 정도입니다."},"foldDuplicate":{"group":{"name":"같은 댓글 접기","desc":"같은 내용의 댓글이 여러 번 달리면 첫 댓글만 남기고 접습니다. 미리보기에도 적용됩니다."},"name":"사용","desc":"같은 댓글을 한 줄로 접습니다."},"duplicateCount":{"group":{"name":"같은 댓글 접기","desc":"같은 내용의 댓글이 여러 번 달리면 첫 댓글만 남기고 접습니다. 미리보기에도 적용됩니다."},"name":"반복 횟수","desc":"이만큼 반복되면 접습니다."},"duplicateMinLength":{"group":{"name":"같은 댓글 접기","desc":"같은 내용의 댓글이 여러 번 달리면 첫 댓글만 남기고 접습니다. 미리보기에도 적용됩니다."},"name":"최소 글자 수","desc":"이보다 짧은 댓글(ㅋㅋ 등)은 반복돼도 접지 않습니다."}},"toggles":{"reveal":"가린 내용 보기"},"commands":{"blockReveal":"이 페이지에서 가린 내용 보기"}}""", stringify(moduleLabels("block")) as String)
        assertEquals("""{"name":"폰트 교체","description":"페이지 전반의 폰트를 교체합니다.","settings":{"customFonts":{"name":"폰트 이름","desc":"쉼표로 구분한 폰트 이름입니다. 앞의 폰트가 없으면 다음 폰트를 씁니다. (빈칸이면 기본 폰트)"},"changeDCFont":{"name":"디시인사이드 폰트 교체","desc":"미리보기 창 같은 DCRefresher Reborn의 폰트뿐만 아니라 디시인사이드의 폰트와 본문 크기까지 바꿉니다."},"bodyFontSize":{"name":"본문 폰트 크기","desc":"게시글 본문의 폰트 크기입니다. 미리보기 창(미니 미리보기 포함)은 본문과 댓글 모두 +2px로 표시됩니다."}}}""", stringify(moduleLabels("fonts")) as String)
