        assertEquals("""{"name":"미리보기","description":"글 목록에서 클릭 또는 우클릭으로 미리보기 창을 띄워 줍니다.","settings":{"previewWidth":{"group":{"name":"미리보기 창","desc":"미리보기 창의 너비와 바깥 배경입니다."},"name":"창 너비","desc":"미리보기 창의 너비입니다. 브라우저 창이 좁으면 그에 맞춰 줄어듭니다."},"toggleBackgroundBlur":{"group":{"name":"미리보기 창","desc":"미리보기 창의 너비와 바깥 배경입니다."},"name":"바깥 배경 흐리게","desc":"미리보기 창 바깥 배경을 흐리게 처리합니다. (성능이 떨어질 수 있음)"},"popupBlur":{"name":"팝업 바깥 배경 흐리게","desc":"메모, 차단 같은 팝업 창 바깥 배경을 흐리게 처리합니다."},"scrollToSkip":{"name":"스크롤하여 게시글 이동","desc":"미리보기 맨 아래에서 한 번 더 스크롤하면 이전(번호가 작은) 게시글로, 맨 위에서는 다음(번호가 큰) 게시글로 넘어갑니다."},"reversePreviewKey":{"name":"미리보기 키 반전","desc":"좌클릭으로 미리보기를 열고 우클릭으로 게시글로 이동합니다. 댓글 수도 같습니다."},"longPressDelay":{"name":"길게 누르기 판정 시간","desc":"마우스 오른쪽 버튼을 이 시간 이상 눌렀다 뗄 때 기본 우클릭 메뉴가 나오게 합니다. (Windows 전용 - Shift+우클릭은 어디서나 기본 메뉴)"},"colorPreviewLink":{"name":"주소창에 게시글 주소 표시","desc":"미리보기를 여는 동안 주소창과 탭 제목을 그 게시글로 바꿉니다. 연 글은 방문 기록에 남아 목록에서 방문한 글 색으로 보입니다."},"autoRefreshComment":{"name":"댓글 자동 새로고침","desc":"일정 주기로 댓글을 자동으로 새로고침합니다."},"highlightNewComments":{"name":"새 댓글 강조","desc":"댓글을 새로고침했을 때 새로 들어온 댓글을 잠깐 강조합니다."},"commentRefreshInterval":{"name":"댓글 자동 새로고침 주기","desc":"댓글 자동 새로고침 주기입니다."},"expandRecognizeRange":{"name":"게시글 인식 범위 확장","desc":"행 전체를 클릭해도 미리보기가 열리게 합니다."},"imageViewer":{"name":"이미지 크게 보기","desc":"본문 이미지를 누르면 미리보기 안에서 크게 봅니다. ←/→로 넘깁니다. 끄면 원본 보기를 새 탭으로 엽니다."},"listKeyboard":{"name":"목록 키보드 이동","desc":"J/K로 글을 고르고 Enter로 미리보기, O로 게시글을 엽니다. Esc로 선택을 풉니다."},"disableCache":{"name":"캐시 비활성화","desc":"미리보기 캐시를 사용하지 않습니다."},"archiveArticle":{"name":"삭제된 글과 댓글 보존","desc":"미리보기로 본 지 1분이 안 된 글과 댓글이 삭제되어도 이전 내용을 보여 줍니다. 새로고침한 글 목록에서 사라진 글도 붉게 표시해 남깁니다."},"blockImage":{"name":"이미지 아이콘 없는 게시글 이미지 숨기기","desc":"이미지 아이콘이 없는 게시글에 이미지가 있으면 숨깁니다."}}}""", stringify(moduleLabels("preview")) as String)
        assertEquals("""{"name":"글 목록 새로고침","description":"글 목록을 자동으로 새로고침합니다.","settings":{"refreshRate":{"name":"새로고침 주기","desc":"글 목록을 새로고침하는 주기입니다. 새 글이 올라오는 1페이지에서만 자동으로 새로고침합니다. 새 글이 한동안 없으면 주기를 조금씩 늘려 최대 4배까지 기다립니다. 새 글이 올라오거나 목록 위에서 마우스, 키보드를 쓰면 원래 주기로 돌아옵니다."},"fadeIn":{"name":"새 게시글 효과","desc":"새로 추가된 게시글에 효과를 넣습니다."},"useBetterBrowse":{"name":"페이지 이동 시 목록만 교체","desc":"페이지 번호를 누르면 페이지 전체를 다시 불러오지 않고 목록만 바꿉니다."},"noRefreshOnSearch":{"name":"검색 중 자동 새로고침 안 함","desc":"검색 중에는 자동 새로고침을 하지 않습니다."},"pauseOnHover":{"name":"목록 위에서 자동 새로고침 안 함","desc":"마우스를 글 목록 위에 올려 두는 동안에는 자동 새로고침을 하지 않습니다. 누르려던 글이 밀리지 않습니다."},"titleCount":{"name":"탭 제목에 새 글 수 표시","desc":"다른 창을 보는 동안 들어온 새 글 수를 탭 제목 앞에 (3)처럼 붙입니다. 다른 탭을 보는 동안에도 세려면 '숨은 탭에서도 새로고침'을 켜세요. 탭으로 돌아오면 지웁니다."},"readMark":{"name":"'여기까지 읽음' 선 표시","desc":"다른 창이나 탭을 보는 동안 새 글이 들어왔으면, 돌아올 때 그동안 들어온 글 아래에 '여기까지 읽음' 선을 긋습니다. 다음에 돌아올 때까지 남습니다."},"backgroundRefresh":{"group":{"name":"숨은 탭","desc":"다른 탭을 보는 동안의 새로고침입니다."},"name":"숨은 탭에서도 새로고침","desc":"다른 탭을 보는 동안에도 아래 주기로 새로고침합니다. 끄면 탭으로 돌아올 때까지 쉽니다."},"backgroundRefreshRate":{"group":{"name":"숨은 탭","desc":"다른 탭을 보는 동안의 새로고침입니다."},"name":"숨은 탭 새로고침 주기","desc":"숨은 탭의 새로고침 주기입니다. 새 글이 한동안 없으면 이 주기도 최대 4배까지 늘어납니다."},"doNotColorVisited":{"name":"방문한 글 색 구분 안 함","desc":"글 목록에서 방문한 글도 방문하지 않은 글과 같은 색으로 표시합니다."}},"toggles":{"pause":"자동 새로고침 일시정지"},"commands":{"refreshLists":"새로고침","refreshPause":"자동 새로고침 일시정지"}}""", stringify(moduleLabels("refresh")) as String)
        assertEquals("""{"name":"검색","description":"검색 결과가 한 쪽에 못 미치면 다음 구간을 이어 붙이고, 아이디, IP로 한 사람의 글을 찾습니다.","settings":{"maxSearches":{"name":"최대 다음 검색 횟수","desc":"한 번에 이어서 검색할 최대 횟수입니다."}}}""", stringify(moduleLabels("search")) as String)
        assertEquals("""{"name":"스텔스 모드","description":"페이지에 표시되는 이미지를 숨깁니다.","toggles":{"reveal":"이미지 잠시 보이기"},"commands":{"stealthPause":"이미지 잠시 보이기"}}""", stringify(moduleLabels("stealth")) as String)
        assertEquals("""{"name":"글쓰기","description":"글쓰기 페이지를 변경합니다.","settings":{"preventExit":{"name":"나가기 방지","desc":"작성 중인 글이 있으면 페이지를 나가기 전에 확인합니다."},"webpConvert":{"name":"이미지 WebP 변환","desc":"올리는 이미지를 WebP로 바꿔 용량을 줄입니다. 움직이는 이미지(GIF, APNG)와 WebP, AVIF, WebP로 바꾸면 더 커지는 이미지는 그대로 올립니다."},"webpQuality":{"name":"WebP 품질","desc":"낮을수록 용량이 줄고 화질이 떨어집니다."},"webpConcurrency":{"name":"동시 변환 수","desc":"여러 장을 한꺼번에 바꾸는 수입니다. 높을수록 빠르지만 메모리를 더 씁니다."},"obfuscateName":{"name":"이미지 이름 숨기기","desc":"올리는 이미지의 파일 이름을 무작위로 바꿉니다."}}}""", stringify(moduleLabels("write")) as String)
    }

    @Test
    fun settingsInTheSameGroupShareTheSameGroupObject() {
        val block = moduleLabels("block")
        assertSame(block.settings.blur.group, block.settings.blurReveal.group)
        assertSame(block.settings.blur.group, block.settings.blurStrength.group)
        assertSame(block.settings.foldDuplicate.group, block.settings.duplicateCount.group)
        val preview = moduleLabels("preview")
        assertSame(preview.settings.previewWidth.group, preview.settings.toggleBackgroundBlur.group)
        val refresh = moduleLabels("refresh")
        assertSame(refresh.settings.backgroundRefresh.group, refresh.settings.backgroundRefreshRate.group)
    }
}
